Cypher query: MATCH p=(a:__Entity__)-[*1..3]-(b:__Entity__)
WHERE a <> b
  AND (
    (toLower(a.name) CONTAINS "monsoon" AND toLower(a.name) CONTAINS "wind")
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS "monsoon" AND toLower(alias) CONTAINS "wind")
    OR (toLower(a.name) CONTAINS "sailing" AND toLower(a.name) CONTAINS "ship")
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS "sailing" AND toLower(alias) CONTAINS "ship")
    OR (toLower(a.name) CONTAINS "trade" AND toLower(a.name) CONTAINS "route")
    OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS "trade" AND toLower(alias) CONTAINS "route")
  )
  AND (
    (toLower(b.name) CONTAINS "monsoon" AND toLower(b.name) CONTAINS "wind")
    OR any(alias IN coalesce(b.aliases, []) WHERE toLower(alias) CONTAINS "monsoon" AND toLower(alias) CONTAINS "wind")
    OR (toLower(b.name) CONTAINS "sailing" AND toLower(b.name) CONTAINS "ship")
    OR any(alias IN coalesce(b.aliases, []) WHERE toLower(alias) CONTAINS "sailing" AND toLower(alias) CONTAINS "ship")
    OR (toLower(b.name) CONTAINS "trade" AND toLower(b.name) CONTAINS "route")
    OR any(alias IN coalesce(b.aliases, []) WHERE toLower(alias) CONTAINS "trade" AND toLower(alias) CONTAINS "route")
  )
RETURN [node IN nodes(p) | node.name] AS entities, [rel IN relationships(p) | type(rel)] AS relationships
LIMIT 10
